}: OAuthManualInputPanelProps) {
  const t = useTranslations("oauthModal");
  const { copied, copy } = useCopyToClipboard();

  return (
    <>
      <div className="space-y-4">
        <OAuthRemoteAccessNotices
          isGoogleOAuth={isGoogleOAuth}
          isTrueLocalhost={isTrueLocalhost}
          googleHint={googleHint}
        />
        <div>
          <p className="text-sm font-medium mb-2">{t("step1OpenUrl")}</p>
          <div className="flex gap-2">
            <Input value={authUrl} readOnly className="flex-1 font-mono text-xs" />
            <Button
              variant="secondary"
              icon={copied === "auth_url" ? "check" : "content_copy"}
              onClick={() => copy(authUrl, "auth_url")}
            >
              {t("copy")}
            </Button>
          </div>
        </div>
        <div>
          <p className="text-sm font-medium mb-2">{t("step2PasteCallback")}</p>
          <p className="text-xs text-text-muted mb-2">
            {t.rich("step2Hint", {
              code: (chunks) => <code className="font-mono">{chunks}</code>,
            })}
          </p>
          <Input
            value={callbackUrl}
            onChange={(event) => onCallbackUrlChange(event.target.value)}
            placeholder={
              provider === "claude" || provider === "cline"
                ? "code#state or /callback?code=..."
                : placeholderUrl
            }
            className="font-mono text-xs"
          />
        </div>
      </div>
      <div className="flex gap-2">
        <Button onClick={onSubmit} fullWidth disabled={!canSubmit}>
          {t("connect")}
        </Button>
        <Button onClick={onClose} variant="ghost" fullWidth>
          {t("cancel")}
        </Button>
      </div>
    </>
  );
}

"use client";

import { useState, useCallback, useRef } from "react";
import { copyToClipboard } from "@/shared/utils/clipboard";

/**
 * Hook for copy to clipboard with feedback.
 * Uses shared copyToClipboard utility that works on both HTTP and HTTPS.
 * @param {number} resetDelay - Time in ms before resetting copied state (default: 2000)
 * @returns {{ copied: string|null, copy: (text: string, id?: string) => Promise<boolean> }}
 */
export function useCopyToClipboard(resetDelay = 2000) {
  const [copied, setCopied] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const copy = useCallback(
    async (text: string, id = "default"): Promise<boolean> => {
      const success = await copyToClipboard(text);

      if (success) {
        setCopied(id);

        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }

        timeoutRef.current = setTimeout(() => {
          setCopied(null);
        }, resetDelay);
      }

      return success;
    },
    [resetDelay]
  );

  return { copied, copy };
}

/**
 * Clipboard utility with HTTP/HTTPS fallback.
 * navigator.clipboard.writeText() requires HTTPS (secure context).
 * For HTTP deployments, falls back to execCommand('copy').
 */

/**
 * Copy text to clipboard with automatic HTTPS/HTTP fallback.
 * Works in both secure (HTTPS) and non-secure (HTTP) contexts.
 * @param text - Text to copy to clipboard
 * @returns true if copy succeeded, false otherwise
 */
export async function copyToClipboard(text: string): Promise<boolean> {
  // Method 1: Clipboard API
  // Works on HTTPS, localhost (treated as secure context), and some browsers
  // even on HTTP. Try unconditionally — the catch handles failures.
  if (typeof navigator !== "undefined" && navigator.clipboard) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch {
      // Fall through to execCommand fallback
    }
  }

  // Method 2: Legacy execCommand fallback (works on HTTP)
  if (typeof document !== "undefined" && document.body) {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.cssText = "position:fixed;top:0;left:-9999px;opacity:0;pointer-events:none;";
    let appended = false;

    try {
      document.body.appendChild(textArea);
      appended = true;
      textArea.focus();
      textArea.select();
      return document.execCommand("copy");
    } catch {
      return false;
    } finally {
      if (appended && document.body.contains(textArea)) {
        document.body.removeChild(textArea);
      }
    }
  }

  return false;
}

/**
 * API utility functions for making HTTP requests
 */

const DEFAULT_HEADERS: Record<string, string> = {
  "Content-Type": "application/json",
};

interface ApiOptions extends RequestInit {
  headers?: Record<string, string>;
}

export async function get(url: string, options: ApiOptions = {}) {
  const response = await fetch(url, {
    ...options,
    method: "GET",
    headers: { ...DEFAULT_HEADERS, ...options.headers },
  });
  return handleResponse(response);
}

export async function post(url: string, data: unknown, options: ApiOptions = {}) {
  const response = await fetch(url, {
    ...options,
    method: "POST",
    headers: { ...DEFAULT_HEADERS, ...options.headers },
    body: JSON.stringify(data),
  });
  return handleResponse(response);
}

export async function put(url: string, data: unknown, options: ApiOptions = {}) {
  const response = await fetch(url, {
    ...options,
    method: "PUT",
    headers: { ...DEFAULT_HEADERS, ...options.headers },
    body: JSON.stringify(data),
  });
  return handleResponse(response);
}

export async function del(url: string, options: ApiOptions = {}) {
  const response = await fetch(url, {
    ...options,
    method: "DELETE",
    headers: { ...DEFAULT_HEADERS, ...options.headers },
  });
  return handleResponse(response);
}

/**
 * Safely read a fetch `Response` body. Returns the parsed JSON when the body is
 * JSON, the raw text when it is not, or `null` when empty. Never throws on a
 * non-JSON body — a plain-text `500 Internal Server Error` no longer surfaces to
 * the caller as `Unexpected token 'I'…`. (#1318) The body is read exactly once,
 * so pass the returned value to {@link getErrorMessage} rather than re-reading
 * the response.
 */
export async function parseResponseBody(response: Response): Promise<unknown> {
  const text = await response.text();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

/**
 * Extract a human-readable error message from an already-parsed response body
 * (see {@link parseResponseBody}), regardless of whether it is a JSON object
 * (`{ error }` / `{ error: { message } }` / `{ message }`) or plain text. Falls
 * back to a status-qualified default. (#1318)
 */
export function getErrorMessage(
  body: unknown,
  status?: number,
  fallback = "Request failed"
): string {
  if (body && typeof body === "object") {
    const rec = body as Record<string, unknown>;
    const err = rec.error;
    if (typeof err === "string" && err.trim()) return err;
    if (err && typeof err === "object") {
      const message = (err as Record<string, unknown>).message;
      if (typeof message === "string" && message.trim()) return message;
      return JSON.stringify(err);
    }
    const msg = rec.message ?? rec.detail;
    if (typeof msg === "string" && msg.trim()) return msg;
  }
  if (typeof body === "string" && body.trim()) {
    return body.length > 300 ? `${body.slice(0, 300)}…` : body;
  }
  return status != null ? `${fallback} (HTTP ${status})` : fallback;
}

async function handleResponse(response: Response) {
  const data = await parseResponseBody(response);

  if (!response.ok) {
    const error: any = new Error(getErrorMessage(data, response.status, "An error occurred"));
    error.status = response.status;
    error.data = data;
    throw error;
  }

  return data;
}

const api = { get, post, put, del };
export default api;

import { parseResponseBody, getErrorMessage } from "@/shared/utils/api";
import { CREDENTIAL_BLOB_PREFIX } from "@/lib/oauth/credentialBlob";

/**
 * Helpers for the remote-login "paste credentials" path in OAuthModal.
 *
 * Google's native-loopback consent can't complete on a remote install, so the
 * user runs `omniroute login antigravity` locally and pastes the credential blob
 * it prints into the modal's Step 2 field. Extracted from OAuthModal to keep that
 * (god-file) component within its frozen size budget.
 */

/** True if the pasted text is a credential blob (vs a callback URL / auth code). */
export function isCredentialBlob(value: string): boolean {
  return typeof value === "string" && value.trim().startsWith(CREDENTIAL_BLOB_PREFIX);
}

/**
 * POST a pasted credential blob to the paste-credentials endpoint. On success it
 * advances the modal to the success step and fires onSuccess; on failure it
 * THROWS so the caller's existing try/catch surfaces the error (keeps the modal
 * call site to two lines). Decoding + finalize + persist happen server-side.
 */
export async function submitCredentialBlob(
  provider: string,
  blob: string,
  reauthConnection: { id?: string } | null | undefined,
  setStep: (s: string) => void,
  onSuccess?: () => void
): Promise<void> {
  const res = await fetch(`/api/oauth/${provider}/paste-credentials`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ blob: blob.trim(), connectionId: reauthConnection?.id }),
  });
  const data = (await parseResponseBody(res)) as Record<string, unknown>;
  if (!res.ok) {
    throw new Error(getErrorMessage(data, res.status, "Failed to import credentials"));
  }
  setStep("success");
  onSuccess?.();
}

/**
 * Paste-safe credential blob codec for the remote OAuth login helper.
 *
 * Why this exists: Google's `firstparty/nativeapp` consent for embedded desktop
 * clients (Antigravity/agy) only releases the authorization code when the
 * loopback redirect (127.0.0.1:<port>) is reachable. On a remote VPS install the
 * loopback is unreachable, so the consent hangs and never emits a code — there is
 * nothing for the user to paste back. (The same flow works locally and over an SSH
 * tunnel because then the loopback IS reachable.)
 *
 * The workaround: a local helper (`omniroute login antigravity`) runs the OAuth on
 * the user's own machine (loopback reachable → consent completes → tokens), then
 * encodes the raw token response into a single-line blob with this codec. The user
 * pastes the blob into the remote dashboard, which decodes it and persists the
 * connection (running the provider's post-exchange/onboarding from the server,
 * which CAN reach Google's Cloud Code APIs).
 *
 * Format: `<prefix><base64url(JSON)>` — a recognizable prefix so humans and the
 * decoder can identify it, followed by a URL/shell-safe base64url payload (no
 * `+`, `/`, `=`, or whitespace) so it survives copy-paste through terminals.
 */

/** Human-recognizable, copy-paste-safe prefix. The decoder requires it. */
export const CREDENTIAL_BLOB_PREFIX = "omniroute-cred-v1.";

/** Current blob schema version (embedded in the payload as `v`). */
const CREDENTIAL_BLOB_VERSION = 1;

export interface CredentialBlobTokens {
  access_token?: string;
  refresh_token?: string;
  id_token?: string;
  expires_in?: number;
  scope?: string;
  [key: string]: unknown;
}

export interface CredentialBlob {
  provider: string;
  tokens: CredentialBlobTokens;
}

/**
 * Encode a provider + raw OAuth token response into a single-line blob.
 * Throws if `provider` is missing — a blob with no provider cannot be routed.
 */
export function encodeCredentialBlob(input: CredentialBlob): string {
  if (!input || typeof input.provider !== "string" || !input.provider.trim()) {
    throw new Error("encodeCredentialBlob: a non-empty provider is required");
  }
  if (!input.tokens || typeof input.tokens !== "object") {
    throw new Error("encodeCredentialBlob: tokens object is required");
  }
  const payload = {
    v: CREDENTIAL_BLOB_VERSION,
    provider: input.provider.trim(),
    tokens: input.tokens,
  };
  const json = JSON.stringify(payload);
  const b64 = Buffer.from(json, "utf8").toString("base64url");
  return `${CREDENTIAL_BLOB_PREFIX}${b64}`;
}

/**
 * Decode a credential blob produced by {@link encodeCredentialBlob}.
 * Validates the prefix, version, JSON shape, and the presence of an access_token.
 * Throws a descriptive error on any malformed/tampered/unsupported input.
 */
export function decodeCredentialBlob(blob: string): CredentialBlob {
  if (typeof blob !== "string" || !blob.startsWith(CREDENTIAL_BLOB_PREFIX)) {
    throw new Error(
      `decodeCredentialBlob: invalid format — must start with "${CREDENTIAL_BLOB_PREFIX}"`
    );
  }
  const b64 = blob.slice(CREDENTIAL_BLOB_PREFIX.length).trim();
  if (!/^[A-Za-z0-9_-]+$/.test(b64)) {
    throw new Error("decodeCredentialBlob: invalid payload — not base64url");
  }

  let parsed: { v?: unknown; provider?: unknown; tokens?: unknown };
  try {
    const json = Buffer.from(b64, "base64url").toString("utf8");
    parsed = JSON.parse(json);
  } catch {
    throw new Error("decodeCredentialBlob: invalid payload — could not parse JSON");
  }

  if (parsed.v !== CREDENTIAL_BLOB_VERSION) {
    throw new Error(
      `decodeCredentialBlob: unsupported blob version ${String(parsed.v)} (expected ${CREDENTIAL_BLOB_VERSION})`
    );
  }
  if (typeof parsed.provider !== "string" || !parsed.provider.trim()) {
    throw new Error("decodeCredentialBlob: invalid payload — missing provider");
  }
  const tokens = parsed.tokens as CredentialBlobTokens | undefined;
  if (!tokens || typeof tokens !== "object") {
    throw new Error("decodeCredentialBlob: invalid payload — missing tokens");
  }
  if (typeof tokens.access_token !== "string" || !tokens.access_token) {
    throw new Error("decodeCredentialBlob: invalid payload — missing access_token");
  }

  return { provider: parsed.provider.trim(), tokens };
}

/**
 * Codex (OpenAI) session-JSON normalizer
 *
 * Accepts the raw JSON object copied straight from
 * `https://chatgpt.com/api/auth/session` (`{ user: {...}, accessToken, expires }`,
 * NextAuth's session-endpoint shape) and extracts a bare access token + optional
 * email, the same credential type already accepted by the bare-token import path
 * (`POST /api/oauth/codex/import-token`, #1290) — this module only widens what
 * shapes of pasted input can reach that endpoint.
 *
 * Pure: no I/O, no network, no DB import. Safe to unit-test. Mirrors the style
 * of `codexAuthImport.ts` / `codexImport.ts`, deliberately kept separate from
 * both: the bulk `auth.json` import requires a `refresh_token`; this path is
 * for a bare access token and deliberately does not.
 *
 * Ref: #6636
 */

import { decodeJwtExp } from "@/lib/oauth/services/codexImport";

// ── Types ─────────────────────────────────────────────────────────────────────

export type ParsedCodexSession = { accessToken: string; email?: string };
export type ParseResult = { ok: true; session: ParsedCodexSession } | { ok: false; error: string };

// ── Internal helpers ──────────────────────────────────────────────────────────

function toRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function toNonEmptyString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

/** Looks like a JWT (3 dot-separated segments) — a loose shape check only. */
function looksLikeJwt(value: string): boolean {
  return value.split(".").length === 3;
}

/**
 * Field-name aliases for the access token across known Codex/ChatGPT session
 * export shapes: the literal `accessToken` returned by `chatgpt.com/api/auth/session`
 * first, then snake_case and alternate names, then the same aliases nested one
 * level under `tokens` (mirrors `unwrapCodexAuthJson` in `codexAuthImport.ts`).
 */
function findAccessToken(rec: Record<string, unknown>): string | undefined {
  const direct =
    toNonEmptyString(rec.accessToken) ||
    toNonEmptyString(rec.access_token) ||
    toNonEmptyString(rec.sessionToken) ||
    toNonEmptyString(rec.session_token);
  if (direct) return direct;

  const nested = toRecord(rec.tokens);
  if (!nested) return undefined;
  return toNonEmptyString(nested.access_token) || toNonEmptyString(nested.accessToken);
}

/** True when either expiry signal (top-level `expires` ISO string, or JWT `exp`) is in the past. */
function isExpired(rec: Record<string, unknown>, accessToken: string): boolean {
  const expiresField = toNonEmptyString(rec.expires);
  if (expiresField) {
    const ms = Date.parse(expiresField);
    if (Number.isFinite(ms) && ms <= Date.now()) return true;
  }
  const exp = decodeJwtExp(accessToken);
  return exp !== null && exp * 1000 <= Date.now();
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * True if the pasted text looks like a JSON object (vs a bare JWT or an OAuth
 * callback URL/code) — a cheap guard so the modal only attempts the JSON
 * normalizer on plausible input and every other paste shape falls through to
 * the existing parsers unchanged.
 */
export function looksLikeCodexSessionJson(value: string): boolean {
  const trimmed = typeof value === "string" ? value.trim() : "";
  if (!trimmed.startsWith("{")) return false;
  try {
    return toRecord(JSON.parse(trimmed)) !== null;
  } catch {
    return false;
  }
}

/**
 * Extract a bare access token (+ optional email) from a parsed
 * `chatgpt.com/api/auth/session`-shaped JSON value. Returns a typed error
 * (never throws) for malformed, tokenless, or expired input.
 */
export function parseCodexSessionJson(raw: unknown): ParseResult {
  const rec = toRecord(raw);
  if (!rec) {
    return { ok: false, error: "Pasted session data is not a JSON object" };
  }

  const accessToken = findAccessToken(rec);
  if (!accessToken) {
    return {
      ok: false,
      error:
        "Could not find an access token field in the pasted session JSON (expected accessToken, access_token, sessionToken, or tokens.access_token)",
    };
  }
  if (!looksLikeJwt(accessToken)) {
    return { ok: false, error: "The access token field does not look like a valid JWT" };
  }

  if (isExpired(rec, accessToken)) {
    return {
      ok: false,
      error: "Session is expired — sign in to chatgpt.com again and re-copy the session JSON",
    };
  }

  const user = toRecord(rec.user);
  const email = (user && toNonEmptyString(user.email)) || undefined;

  return { ok: true, session: { accessToken, email } };
}

/**
 * Codex (OpenAI) bulk-import normalization
 *
 * Accepts the JSON shape produced by Codex CLI / common token-export tools and
 * returns a {@link createProviderConnection} payload (or a typed error).
 *
 * Pure: no I/O, no network. Safe to unit-test.
 *
 * Ported from decolua/9router#1257 (beaaan).
 */

const REQUIRED_FIELDS = ["access_token", "refresh_token"] as const;

/** 10 days — the typical OpenAI access-token lifetime when no `expired` is supplied. */
const DEFAULT_EXPIRY_MS = 10 * 24 * 60 * 60 * 1000;

const BASE64_BLOCK_SIZE = 4;

// ── Types ─────────────────────────────────────────────────────────────────────

export type CodexImportPayload = {
  provider: "codex";
  authType: "oauth";
  accessToken: string;
  refreshToken: string;
  idToken?: string;
  email: string;
  expiresAt: string;
  testStatus: "active";
  providerSpecificData?: {
    chatgptAccountId?: string;
    chatgptPlanType?: string;
  };
};

export type NormalizeOk = { ok: true; payload: CodexImportPayload };
export type NormalizeErr = { ok: false; error: string };
export type NormalizeResult = NormalizeOk | NormalizeErr;

export type FlattenOk = { ok: true; records: unknown[] };
export type FlattenErr = { ok: false; error: string };
export type FlattenResult = FlattenOk | FlattenErr;

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Decode a JWT payload to a plain object (no signature verification).
 *
 * Mirrors the helper in `providers.ts` but is kept local so this module has no
 * runtime dependency on the larger OAuth module graph.
 */
function decodeJwtPayload(jwt: unknown): Record<string, unknown> | null {
  try {
    if (!jwt || typeof jwt !== "string") return null;
    const parts = jwt.split(".");
    if (parts.length !== 3) return null;
    const base64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const missingPadding =
      (BASE64_BLOCK_SIZE - (base64.length % BASE64_BLOCK_SIZE)) % BASE64_BLOCK_SIZE;
    const padded = base64 + "=".repeat(missingPadding);
    return JSON.parse(Buffer.from(padded, "base64").toString("utf8")) as Record<string, unknown>;
  } catch {
    return null;
  }
}

/**
 * Decode a Codex JWT (id_token, or a bare ChatGPT access token — both carry
 * the same `https://api.openai.com/auth` custom claim) into account info.
 *
 * Exported so other Codex import paths (e.g. the bare-access-token import at
 * `/api/oauth/codex/import-token`, #1290) can reuse this decode logic instead
 * of duplicating an inline JWT decode.
 */
export function extractCodexAccountInfo(idToken: string): {
  email?: string;
  chatgptAccountId?: string;
  chatgptPlanType?: string;
} {
  const payload = decodeJwtPayload(idToken);
  if (!payload) return {};
  const chatgpt = (payload["https://api.openai.com/auth"] as Record<string, unknown>) || {};
  return {
    email: typeof payload.email === "string" ? payload.email : undefined,
    chatgptAccountId:
      typeof chatgpt.chatgpt_account_id === "string" ? chatgpt.chatgpt_account_id : undefined,
    chatgptPlanType:
      typeof chatgpt.chatgpt_plan_type === "string" ? chatgpt.chatgpt_plan_type : undefined,
  };
}

/**
 * Decode a JWT's `exp` claim (seconds since epoch, per RFC 7519) without
 * verifying the signature. Returns `null` when the token isn't a decodable
 * JWT or carries no numeric `exp`.
 *
 * Exported so sibling Codex import paths (e.g. the session-JSON normalizer
 * at `codexSessionImport.ts`, #6636) can check expiry without duplicating a
 * 3rd inline JWT decoder.
 */
export function decodeJwtExp(jwt: unknown): number | null {
  const payload = decodeJwtPayload(jwt);
  const exp = payload && typeof payload.exp === "number" ? payload.exp : null;
  return exp !== null && Number.isFinite(exp) ? exp : null;
}

function pickString(...candidates: (string | undefined)[]): string | undefined {
  for (const c of candidates) {
    if (typeof c === "string" && c.trim()) return c.trim();
  }
  return undefined;
}

function parseExpiry(value: unknown): string | undefined {
  if (typeof value === "string" && value) {
    const ms = Date.parse(value);
    if (Number.isFinite(ms)) return new Date(ms).toISOString();
  }
  return undefined;
}

function parseAccessTokenExp(accessToken: string): string {
  const payload = decodeJwtPayload(accessToken);
  const exp = payload && typeof payload.exp === "number" ? payload.exp : null;
  if (exp && Number.isFinite(exp)) {
    return new Date(exp * 1000).toISOString();
  }
  return new Date(Date.now() + DEFAULT_EXPIRY_MS).toISOString();
}

/**
 * Codex CLI persists tokens to `auth.json` with the OAuth fields nested under
 * a `tokens` object: `{ auth_mode, OPENAI_API_KEY, tokens: { id_token, ... } }`.
 * Flatten that into the same shape as a simple top-level export so the rest of
 * the normalizer can stay unchanged.
 */
function unwrapCodexAuthJson(rec: Record<string, unknown>): Record<string, unknown> {
  const tokens = rec.tokens as Record<string, unknown> | undefined;
  if (!tokens || typeof tokens !== "object" || Array.isArray(tokens)) {
    return rec;
  }
  if (typeof tokens.access_token !== "string") return rec;
  // Tokens take priority; carry through siblings (email / account_id / expired)
  // only when the nested object doesn't already define them.
  return { ...rec, ...tokens };
}

/**
 * Map the camelCase field names used by 9router's Codex account export
 * (`accessToken`, `refreshToken`, `idToken`, `expiresAt`, and a nested
 * `providerSpecificData` block) onto the snake_case keys the rest of the
 * normalizer already understands (#6665). A snake_case key is only filled from
 * its camelCase alias when it is absent, so a snake_case or mixed export keeps
 * working unchanged.
 */
function applyCamelCaseAliases(rec: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { ...rec };
  const fillFrom = (snake: string, value: unknown) => {
    if (out[snake] === undefined && typeof value === "string" && value) {
      out[snake] = value;
    }
  };
  fillFrom("access_token", rec.accessToken);
  fillFrom("refresh_token", rec.refreshToken);
  fillFrom("id_token", rec.idToken);
  fillFrom("expired", rec.expiresAt);
  const psd = rec.providerSpecificData;
  if (psd && typeof psd === "object" && !Array.isArray(psd)) {
    const block = psd as Record<string, unknown>;
    fillFrom("account_id", block.chatgptAccountId);
    fillFrom("chatgpt_plan_type", block.chatgptPlanType);
  }
  return out;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Normalize a single raw record from an uploaded JSON file into a
 * `createProviderConnection` payload.
 *
 * @param input — single record from the uploaded JSON
 */
export function normalizeCodexImportRecord(input: unknown): NormalizeResult {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return { ok: false, error: "Record is not an object" };
  }

  const rec = applyCamelCaseAliases(unwrapCodexAuthJson(input as Record<string, unknown>));

  // Allow type field to be missing or "codex"; reject anything else explicitly so
  // users don't accidentally import claude/gemini exports through this path.
  if (rec.type !== undefined && rec.type !== null && rec.type !== "codex") {
    return { ok: false, error: `Unsupported type: ${String(rec.type)}` };
  }

  for (const f of REQUIRED_FIELDS) {
    if (typeof rec[f] !== "string" || !rec[f]) {
      return { ok: false, error: `Missing required field: ${f}` };
    }
  }

  const accessToken = String(rec.access_token);
  const refreshToken = String(rec.refresh_token);
  const idToken = typeof rec.id_token === "string" ? rec.id_token : undefined;

  // Prefer JWT-derived account info, fall back to top-level fields.
  const fromJwt = idToken ? extractCodexAccountInfo(idToken) : {};
  const email = pickString(fromJwt.email, rec.email as string | undefined);

  if (!email) {
    return { ok: false, error: "Missing email (and id_token does not contain one)" };
  }

  const chatgptAccountId = pickString(
    fromJwt.chatgptAccountId,
    rec.account_id as string | undefined
  );
  const chatgptPlanType = pickString(
    fromJwt.chatgptPlanType,
    rec.chatgpt_plan_type as string | undefined
  );

  const expiresAt = parseExpiry(rec.expired) ?? parseAccessTokenExp(accessToken);

  const providerSpecificData: CodexImportPayload["providerSpecificData"] = {};
  if (chatgptAccountId) providerSpecificData.chatgptAccountId = chatgptAccountId;
  if (chatgptPlanType) providerSpecificData.chatgptPlanType = chatgptPlanType;

  const payload: CodexImportPayload = {
    provider: "codex",
    authType: "oauth",
    accessToken,
    refreshToken,
    email,
    expiresAt,
    testStatus: "active",
  };
  if (idToken) payload.idToken = idToken;
  if (Object.keys(providerSpecificData).length > 0) {
    payload.providerSpecificData = providerSpecificData;
  }

  return { ok: true, payload };
}

/**
 * Flatten the user-uploaded JSON into an array of candidate records.
 * Accepts a single record or an array; rejects anything else.
 */
export function flattenCodexImportPayload(parsed: unknown): FlattenResult {
  if (Array.isArray(parsed)) {
    return { ok: true, records: parsed };
  }
  if (parsed && typeof parsed === "object") {
    return { ok: true, records: [parsed] };
  }
  return { ok: false, error: "JSON must be an object or an array of objects" };
}

