  if (isOpenAICompatibleProvider(aliasOrId)) return true;
  if (isAnthropicCompatibleProvider(aliasOrId)) return true;
  if (PASSTHROUGH_PROVIDERS.has(aliasOrId)) return true;
  const models = MODELS[aliasOrId];
