export function stripHyperAgentModelPrefix(model: string): string {
  let m = (model || "").trim();
  if (m.startsWith("hyperagent/")) m = m.slice("hyperagent/".length);
  else if (m.startsWith("ha/")) m = m.slice(3);
  else if (m.startsWith("hyper/")) m = m.slice("hyper/".length);
  return m;
}

/** Alias / pretty-name / legacy pricing-key → catalog wire id. */
const ALIASES: Record<string, string> = {
  // Fable
  fable: "fable-latest",
  "fable-5": "fable-latest",
  fable5: "fable-latest",
  "claude-fable-5": "claude-fable-5",
  "claude-fable": "fable-latest",
  "fable-latest": "fable-latest",
  // Opus
  opus: "opus-latest",
  "opus-latest": "opus-latest",
  "opus-4-8": "claude-opus-4-8",
  "opus-4.8": "claude-opus-4-8",
  "claude-opus-4-8": "claude-opus-4-8",
  "claude-opus-4.8": "claude-opus-4-8",
  "claude-opus-latest": "opus-latest",
  // Sonnet
  sonnet: "sonnet-latest",
  "sonnet-latest": "sonnet-latest",
  "sonnet-5": "claude-sonnet-5",
  "claude-sonnet-5": "claude-sonnet-5",
  "claude-sonnet-latest": "sonnet-latest",
  // Haiku subagent only — map main requests to sonnet-latest as closest chat model
  haiku: "sonnet-latest",
  "haiku-4": "sonnet-latest",
  "claude-haiku-4": "sonnet-latest",
};

export function resolveHyperAgentModel(model: unknown): HyperAgentModel | null {
  const raw = typeof model === "string" ? stripHyperAgentModelPrefix(model) : "";
  if (!raw) return null;
  const lower = raw.toLowerCase().trim();
  const compact = lower.replace(/[\s_]+/g, "-");
  const catalog = HYPERAGENT_FALLBACK_MODELS;

  // Exact wire id
  const byId = catalog.find((m) => m.id.toLowerCase() === lower || m.id.toLowerCase() === compact);
  if (byId) return byId;

  // Pretty name
  const byName = catalog.find((m) => m.name.toLowerCase() === lower);
  if (byName) return byName;

  // Alias table
  const aliasId = ALIASES[compact] || ALIASES[lower];
  if (aliasId) {
    const hit = catalog.find((m) => m.id === aliasId);
    if (hit) return hit;
  }

  // Partial contains
  return (
    catalog.find((m) => compact.includes(m.id.toLowerCase())) ||
    catalog.find((m) => m.name.toLowerCase().includes(compact.replace(/-/g, " "))) ||
    null
  );
}

/** Client-facing / OpenAI response model id (wire id). */
export function clientFacingHyperAgentModelId(model: unknown): string {
  const resolved = resolveHyperAgentModel(model);
  if (resolved) return resolved.id;
  const stripped = typeof model === "string" ? stripHyperAgentModelPrefix(model) : "";
  return stripped || "opus-latest";
}

/**
 * Wire modelId for PATCH /api/threads/{id}.
 * Never returns bare "fable" (invalid) — maps to fable-latest.
 */
export function wireHyperAgentModelId(model: unknown): string {
  return clientFacingHyperAgentModelId(model);
}

/**
 * Short subagent family for defaultSubagentModel.
 * Live API accepts only: fable | opus | sonnet | haiku (not *-latest).
 * User request: subagent matches the selected model family.
 */
export function wireHyperAgentSubagentModelId(model: unknown): string {
  const resolved = resolveHyperAgentModel(model);
  if (resolved?.subagent) return resolved.subagent;

  const wire = wireHyperAgentModelId(model).toLowerCase();
  if (wire.includes("fable")) return "fable";
  if (wire.includes("sonnet")) return "sonnet";
  if (wire.includes("haiku")) return "haiku";
  if (wire.includes("opus")) return "opus";
  return "opus";
}

export function wireHyperAgentRuntimeId(model: unknown): string {
  const resolved = resolveHyperAgentModel(model);
  return resolved?.runtimeId || "claude-agents-sdk";
}

import { getModelsByProviderId } from "@/shared/constants/models";
import { isClaudeCodeCompatibleProvider } from "@/shared/constants/providers";

type ManagedAvailableModel = {
  id?: string;
  name?: string;
  contextLength?: number;
};

export function getCompatibleFallbackModels(
  providerId: string,
  fallbackModels: ManagedAvailableModel[] = []
): ManagedAvailableModel[] | undefined {
  if (providerId === "openrouter") return fallbackModels;
  if (isClaudeCodeCompatibleProvider(providerId)) return getModelsByProviderId("claude");
  return undefined;
}

export function compatibleProviderSupportsModelImport(providerId: string): boolean {
  return !isClaudeCodeCompatibleProvider(providerId);
}

export type ModelCatalogSource = "system" | "custom" | "imported" | "fallback" | "alias" | "auto";

type ModelCatalogTarget = {
  modelId?: string | null;
  modelName?: string | null;
  alias?: string | null;
  source?: string | null;
};

function normalizeText(value: string | null | undefined): string {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}

export function normalizeModelCatalogSource(source?: string | null): ModelCatalogSource {
  const normalized = normalizeText(source);

  if (
    normalized === "api-sync" ||
    normalized === "synced" ||
    normalized === "auto-sync" ||
    normalized === "imported"
  ) {
    return "imported";
  }
  if (normalized === "fallback") return "fallback";
  if (normalized === "alias") return "alias";
  // Models discovered live from a custom provider's upstream `/models` endpoint.
  if (normalized === "auto") return "auto";
  if (normalized === "custom" || normalized === "manual") {
    return "custom";
  }

  return "system";
}

export function getModelCatalogSourceLabel(source?: string | null): string {
  switch (normalizeModelCatalogSource(source)) {
    case "imported":
      return "Imported";
    case "custom":
      return "Custom";
    case "fallback":
      return "Fallback";
    case "alias":
      return "Alias";
    case "auto":
      return "Auto";
    case "system":
    default:
      return "Built-in";
  }
}

function getModelCatalogSourceSearchText(source?: string | null): string {
  switch (normalizeModelCatalogSource(source)) {
    case "imported":
      return "synced api imported discovered";
    case "custom":
      return "custom manual imported";
    case "fallback":
      return "fallback compatible";
    case "alias":
      return "alias shortcut";
    case "auto":
      return "auto fetched discovered upstream";
    case "system":
    default:
      return "built-in builtin official catalog";
  }
}

export function matchesModelCatalogQuery(query: string, target: ModelCatalogTarget): boolean {
  const normalizedQuery = normalizeText(query);
  if (!normalizedQuery) return true;

  const haystacks = [
    normalizeText(target.modelId),
    normalizeText(target.modelName),
    normalizeText(target.alias),
    getModelCatalogSourceSearchText(target.source),
  ].filter(Boolean);

  return haystacks.some((value) => value.includes(normalizedQuery));
}

import { wildcardMatch } from "@omniroute/open-sse/services/wildcardRouter.ts";

type JsonRecord = Record<string, unknown>;

interface ConnectionLike {
  providerSpecificData?: unknown;
}

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function normalizePattern(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim();
  if (!normalized || normalized === "**") return null;
  return normalized;
}

function toPatternList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map(normalizePattern).filter((pattern): pattern is string => Boolean(pattern));
  }
  if (typeof value === "string") {
    return value
      .split(",")
      .map(normalizePattern)
      .filter((pattern): pattern is string => Boolean(pattern));
  }
  return [];
}

function uniquePatterns(patterns: string[]): string[] {
  return Array.from(new Set(patterns));
}

function getModelMatchCandidates(modelId: string): string[] {
  const normalized = modelId.trim();
  if (!normalized) return [];

  const withoutExtendedContext = normalized.endsWith("[1m]") ? normalized.slice(0, -4) : normalized;
  const lastSlashIndex = withoutExtendedContext.lastIndexOf("/");
  const rawModel =
    lastSlashIndex >= 0 ? withoutExtendedContext.slice(lastSlashIndex + 1) : withoutExtendedContext;

  return Array.from(new Set([normalized, withoutExtendedContext, rawModel].filter(Boolean)));
}

export function normalizeExcludedModelPatterns(value: unknown): string[] {
  return uniquePatterns(toPatternList(value));
}

export function getConnectionExcludedModels(providerSpecificData: unknown): string[] {
  const data = asRecord(providerSpecificData);
  return normalizeExcludedModelPatterns(data.excludedModels ?? data.excluded_models);
}

export function isModelExcludedByConnection(
  modelId: unknown,
  providerSpecificData: unknown
): boolean {
  if (typeof modelId !== "string" || modelId.trim().length === 0) return false;

  const candidates = getModelMatchCandidates(modelId);
  const excludedModels = getConnectionExcludedModels(providerSpecificData);
  if (candidates.length === 0 || excludedModels.length === 0) return false;

  return excludedModels.some((pattern) =>
    candidates.some((candidate) => wildcardMatch(candidate, pattern))
  );
}

export function hasEligibleConnectionForModel(
  connections: ConnectionLike[] | null | undefined,
  modelId: unknown
): boolean {
  if (!Array.isArray(connections) || connections.length === 0) return false;

  return connections.some(
    (connection) => !isModelExcludedByConnection(modelId, connection?.providerSpecificData)
  );
}

// @ts-nocheck
/**
 * Wildcard Model Routing — Phase 8
 *
 * Glob-style wildcard matching for model aliases with specificity ranking.
 * Integrates into the existing model resolution pipeline.
 */

/**
 * Match a model name against a pattern with glob wildcards.
 * Supports * (wildcard sequence) and ? (single char).
 *
 * @param {string} model - Model name to match
 * @param {string} pattern - Pattern with wildcards
 * @returns {boolean}
 */
export function wildcardMatch(model, pattern) {
  if (!model || !pattern) return false;
  if (pattern === "*") return true;
  if (pattern === model) return true;

  // Convert glob pattern to regex
  const regexStr = pattern
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*/g, ".*")
    .replace(/\?/g, ".");
  const regex = new RegExp(`^${regexStr}$`, "i");
  return regex.test(model);
}

/**
 * Calculate specificity score for a pattern.
 * Higher score = more specific match.
 * Used to rank multiple matching patterns.
 *
 * @param {string} pattern
 * @returns {number} Specificity score (higher = more specific)
 */
export function getSpecificity(pattern) {
  if (!pattern) return 0;

  let score = 0;
  // Exact segments (no wildcards) contribute most
  const segments = pattern.split(/[/*?]/);
  for (const seg of segments) {
    if (seg.length > 0) score += seg.length * 10;
  }
  // Wildcards reduce specificity
  const wildcardCount = (pattern.match(/\*/g) || []).length;
  const questionCount = (pattern.match(/\?/g) || []).length;
  score -= wildcardCount * 50;
  score -= questionCount * 5;
  // Longer patterns tend to be more specific
  score += pattern.length;

  return score;
}

/**
 * Find the best matching alias for a model name from a list of alias entries.
 * Returns the most specific match.
 *
 * @param {string} model - Model name to resolve
 * @param {Array<{ pattern: string, target: string, [key: string]: unknown }>} aliases - Alias entries
 * @returns {{ pattern: string, target: string, specificity: number } | null}
 */
export function resolveWildcardAlias(
  model: string,
  aliases: WildcardAliasEntry[]
): ResolvedWildcardAlias | null {
  if (!model || !aliases || !Array.isArray(aliases)) return null;

  const matches: ResolvedWildcardAlias[] = [];
  for (const alias of aliases) {
    const pattern = alias.pattern || alias.alias || alias.from;
    const target = alias.target || alias.model || alias.to;
    if (!pattern || !target) continue;

    if (wildcardMatch(model, pattern)) {
      matches.push({
        pattern,
        target,
        specificity: getSpecificity(pattern),
        ...alias,
      });
    }
  }

  if (matches.length === 0) return null;

  // Sort by specificity (highest first)
  matches.sort((a, b) => b.specificity - a.specificity);
  return matches[0];
}

/**
 * Resolve model through wildcard aliases, falling back to exact match.
 * Can be integrated into existing model resolution.
 *
 * @param {string} model - Requested model name
 * @param {Map|Object} exactAliases - Exact model alias map
 * @param {Array} wildcardAliases - Wildcard pattern aliases
 * @returns {string} Resolved model name
 */
export function resolveModel(model, exactAliases = {}, wildcardAliases = []) {
  if (!model) return model;

  // 1. Check exact aliases first (fastest)
  if (exactAliases instanceof Map) {
    if (exactAliases.has(model)) return exactAliases.get(model);
  } else if (exactAliases[model]) {
    return exactAliases[model];
  }

  // 2. Check wildcard aliases
  const match = resolveWildcardAlias(model, wildcardAliases);
  if (match) return match.target;

  // 3. Return original
  return model;
}
type WildcardAliasEntry = {
  pattern?: string;
  alias?: string;
  from?: string;
  target?: string;
  model?: string;
  to?: string;
  [key: string]: unknown;
};

type ResolvedWildcardAlias = WildcardAliasEntry & {
  pattern: string;
  target: string;
  specificity: number;
};

"use client";

import { useEffect, useState } from "react";
import Select from "./Select";
import Input from "./Input";

interface ApiModel {
  provider: string;
  model: string;
  fullModel?: string;
}

export interface ModelSelectFieldProps {
  value: string;
  onChange: (value: string) => void;
  disabled?: boolean;
  label?: React.ReactNode;
  placeholder?: string;
  ariaLabel?: string;
  /** Render a plain text fallback (custom option / off-catalog) — default true. */
  allowCustom?: boolean;
  className?: string;
}

interface FetchState {
  status: "loading" | "ready" | "error";
  options: { value: string; label: string }[];
}

/**
 * hidePaid-aware model picker (#6540). Loads options from `GET /api/models`
 * (already filters by `hidePaidModels`) instead of a static catalog. Falls
 * back to a plain text `Input` when the fetch fails so the field never
 * becomes unusable, and injects a "(custom)" option for an existing saved
 * value that isn't present in the fetched catalog (typo, deprecated model,
 * alias/combo name) so it is never silently dropped on save.
 */
export default function ModelSelectField({
  value,
  onChange,
  disabled = false,
  label,
  placeholder,
  ariaLabel,
  allowCustom = true,
  className,
}: ModelSelectFieldProps) {
  const [state, setState] = useState<FetchState>({ status: "loading", options: [] });

  useEffect(() => {
    let cancelled = false;
    fetch("/api/models")
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error("fetch failed"))))
      .then((data) => {
        if (cancelled) return;
        const models: ApiModel[] = Array.isArray(data?.models) ? data.models : [];
        const options = models.map((m) => {
          const full = m.fullModel || `${m.provider}/${m.model}`;
          return { value: full, label: full };
        });
        setState({ status: "ready", options });
      })
      .catch(() => {
        if (!cancelled) setState({ status: "error", options: [] });
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (state.status === "error" && allowCustom) {
    return (
      <Input
        label={label}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        aria-label={ariaLabel}
        className={className}
      />
    );
  }

  const hasKnownValue = value === "" || state.options.some((o) => o.value === value);
  const options =
    !hasKnownValue && allowCustom
      ? [{ value, label: `${value} (custom)` }, ...state.options]
      : state.options;

  return (
    <Select
      label={label}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      options={options}
      placeholder={state.status === "loading" ? "Loading models…" : placeholder || "Select a model"}
      disabled={disabled || state.status === "loading"}
      aria-label={ariaLabel}
      className={className}
    />
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { Button, Card, Input, Select, Toggle } from "@/shared/components";

type RuleScope = "global" | "apiKey" | "combo" | "model" | "connection";
type TargetKind = "keep" | "model" | "combo";
type EffortMode = "inherit" | "default" | "force";
type BudgetAction = "preserve" | "remove" | "set";

type Rule = {
  id: string;
  name: string;
  description: string;
  scope: RuleScope;
  apiKeyId: string | null;
  comboId: string | null;
  connectionId: string | null;
  modelPattern: string | null;
  sourceEffort: string;
  requestTags: string[];
  tagMatchMode: "any" | "all";
  effortMode: EffortMode;
  targetEffort: string | null;
  targetKind: TargetKind;
  targetModel: string | null;
  targetComboId: string | null;
  budgetAction: BudgetAction;
  budgetTokens: number | null;
  priority: number;
  enabled: boolean;
};

type Reference = { id: string; name: string; provider?: string; displayName?: string };

type FormState = {
  name: string;
  description: string;
  scope: RuleScope;
  apiKeyId: string;
  comboId: string;
  connectionId: string;
  modelPattern: string;
  sourceEffort: string;
  requestTags: string;
  tagMatchMode: "any" | "all";
  effortMode: EffortMode;
  targetEffort: string;
  targetKind: TargetKind;
  targetModel: string;
  targetComboId: string;
  budgetAction: BudgetAction;
  budgetTokens: string;
  priority: string;
  enabled: boolean;
};

const STANDARD_EFFORTS = ["none", "low", "medium", "high", "xhigh"];
const EXTENDED_EFFORTS = ["max", "ultra"];

function emptyRule(apiKeyId?: string): FormState {
  return {
    name: "",
    description: "",
    scope: apiKeyId ? "apiKey" : "global",
    apiKeyId: apiKeyId || "",
    comboId: "",
    connectionId: "",
    modelPattern: "",
    sourceEffort: "any",
    requestTags: "",
    tagMatchMode: "any",
    effortMode: "inherit",
    targetEffort: "medium",
    targetKind: "keep",
    targetModel: "",
    targetComboId: "",
    budgetAction: "preserve",
    budgetTokens: "",
    priority: "0",
    enabled: true,
  };
}

function supportsExtendedCodexEffort(model: string, effort: "max" | "ultra"): boolean {
  const normalized = model
    .trim()
    .toLowerCase()
    .replace(/^(?:codex|cx)\//, "");
  return effort === "ultra"
    ? /^gpt-5\.6-(?:sol|terra)(?:-|$)/.test(normalized)
    : /^gpt-5\.6-(?:sol|terra|luna)(?:-|$)/.test(normalized);
}

export default function ReasoningRoutingRules({ apiKeyId }: { apiKeyId?: string }) {
  const t = useTranslations("reasoningRouting");
  const [rules, setRules] = useState<Rule[]>([]);
  const [combos, setCombos] = useState<Reference[]>([]);
  const [keys, setKeys] = useState<Reference[]>([]);
  const [connections, setConnections] = useState<Reference[]>([]);
  const [form, setForm] = useState<FormState>(() => emptyRule(apiKeyId));
  const [editingId, setEditingId] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [scopeFilter, setScopeFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [search, setSearch] = useState("");
  const [simulator, setSimulator] = useState({
    model: "",
    effort: "missing",
    requestTags: "",
    transport: "http",
  });
  const [simulation, setSimulation] = useState<Record<string, unknown> | null>(null);

  const load = useCallback(async () => {
    const responses = await Promise.all([
      fetch("/api/settings/reasoning-routing-rules"),
      fetch("/api/combos"),
      fetch("/api/keys"),
      fetch("/api/providers"),
    ]);
    if (responses.some((response) => !response.ok)) throw new Error(t("loadError"));
    const [ruleData, comboData, keyData, providerData] = await Promise.all(
      responses.map((response) => response.json())
    );
    setRules(Array.isArray(ruleData.rules) ? ruleData.rules : []);
    setCombos(Array.isArray(comboData.combos) ? comboData.combos : []);
    setKeys(Array.isArray(keyData.keys) ? keyData.keys : []);
    setConnections(Array.isArray(providerData.connections) ? providerData.connections : []);
  }, [t]);

  useEffect(() => {
    load().catch(() => setMessage(t("loadError")));
  }, [load, t]);

  const visibleRules = useMemo(() => {
    const query = search.trim().toLowerCase();
    return rules.filter((rule) => {
      if (apiKeyId && (rule.scope !== "apiKey" || rule.apiKeyId !== apiKeyId)) return false;
      if (!apiKeyId && scopeFilter !== "all" && rule.scope !== scopeFilter) return false;
      if (statusFilter === "enabled" && !rule.enabled) return false;
      if (statusFilter === "disabled" && rule.enabled) return false;
      if (!query) return true;
      return [rule.name, rule.description, rule.modelPattern, ...rule.requestTags]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(query));
    });
  }, [apiKeyId, rules, scopeFilter, search, statusFilter]);

  const targetModelForCapability =
    form.targetKind === "model" ? form.targetModel : form.modelPattern;
  const effortOptions = useMemo(() => {
    const values = [...STANDARD_EFFORTS];
    for (const effort of EXTENDED_EFFORTS) {
      if (
        supportsExtendedCodexEffort(targetModelForCapability, effort as "max" | "ultra") ||
        form.targetEffort === effort
      ) {
        values.push(effort);
      }
    }
    return values.map((value) => ({ value, label: value }));
  }, [form.targetEffort, targetModelForCapability]);

  const capabilityWarning = useMemo(() => {
    if (form.effortMode === "inherit") return "";
    if (!EXTENDED_EFFORTS.includes(form.targetEffort)) return "";
    if (form.targetKind === "combo") return t("extendedComboWarning");
    if (!targetModelForCapability.trim()) return t("extendedUnknownWarning");
    return supportsExtendedCodexEffort(
      targetModelForCapability,
      form.targetEffort as "max" | "ultra"
    )
      ? ""
      : t("extendedUnsupportedWarning");
  }, [form.effortMode, form.targetEffort, form.targetKind, t, targetModelForCapability]);

  const reset = () => {
    setEditingId(null);
    setForm(emptyRule(apiKeyId));
  };

  const edit = (rule: Rule) => {
    setEditingId(rule.id);
    setForm({
      ...emptyRule(apiKeyId),
      ...rule,
      apiKeyId: rule.apiKeyId || "",
      comboId: rule.comboId || "",
      connectionId: rule.connectionId || "",
      modelPattern: rule.modelPattern || "",
      targetEffort: rule.targetEffort || "medium",
      targetModel: rule.targetModel || "",
      targetComboId: rule.targetComboId || "",
      requestTags: rule.requestTags.join(", "),
      budgetTokens: rule.budgetTokens ? String(rule.budgetTokens) : "",
      priority: String(rule.priority),
    });
  };

  const payload = () => {
    const targetKind: TargetKind = form.scope === "connection" ? "keep" : form.targetKind;
    return {
      ...form,
      apiKeyId: form.scope === "apiKey" ? form.apiKeyId || null : null,
      comboId: form.scope === "combo" ? form.comboId || null : null,
      connectionId: form.scope === "connection" ? form.connectionId || null : null,
      modelPattern:
        form.scope === "model" || form.scope === "apiKey" ? form.modelPattern || null : null,
      requestTags: form.requestTags
        .split(",")
        .map((tag) => tag.trim())
        .filter(Boolean),
      targetEffort: form.effortMode === "inherit" ? null : form.targetEffort,
      targetKind,
      targetModel: targetKind === "model" ? form.targetModel || null : null,
      targetComboId: targetKind === "combo" ? form.targetComboId || null : null,
      budgetTokens: form.budgetAction === "set" ? Number(form.budgetTokens) : null,
      priority: Number(form.priority),
    };
  };

  const save = async () => {
    setSaving(true);
    setMessage("");
    try {
      const response = await fetch(
        editingId
          ? `/api/settings/reasoning-routing-rules/${encodeURIComponent(editingId)}`
          : "/api/settings/reasoning-routing-rules",
        {
          method: editingId ? "PATCH" : "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload()),
        }
      );
      if (!response.ok) {
        const result = await response.json().catch(() => null);
        throw new Error(result?.error?.message || result?.error || t("saveError"));
      }
      await load();
      reset();
      setMessage(t("saved"));
    } catch (error) {
      setMessage(error instanceof Error ? error.message : t("saveError"));
    } finally {
      setSaving(false);
    }
  };

  const remove = async (id: string) => {
    if (!window.confirm(t("deleteConfirm"))) return;
    const response = await fetch(
      `/api/settings/reasoning-routing-rules/${encodeURIComponent(id)}`,
      { method: "DELETE" }
    );
    if (response.ok) await load();
    else setMessage(t("deleteError"));
  };

  const toggle = async (rule: Rule) => {
    const response = await fetch(
      `/api/settings/reasoning-routing-rules/${encodeURIComponent(rule.id)}`,
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ enabled: !rule.enabled }),
      }
    );
    if (response.ok) await load();
    else setMessage(t("saveError"));
  };

  const simulate = async () => {
    setSimulation(null);
    const response = await fetch("/api/settings/reasoning-routing-rules/simulate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...simulator,
        apiKeyId: apiKeyId || form.apiKeyId || null,
        requestTags: simulator.requestTags
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean),
      }),
    });
    setSimulation(await response.json());
  };

  const scopeOptions = ["global", "apiKey", "combo", "model", "connection"].map((scope) => ({
    value: scope,
    label: t(`scope.${scope}`),
  }));

  return (
    <Card title={apiKeyId ? t("apiKeyTitle") : t("title")} subtitle={t("subtitle")} icon="route">
      <div className="space-y-5">
        <div className="grid gap-3 md:grid-cols-3">
          <Input
            label={t("filterSearch")}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {!apiKeyId && (
            <Select
              label={t("filterScope")}
              value={scopeFilter}
              onChange={(e) => setScopeFilter(e.target.value)}
              options={[{ value: "all", label: t("all") }, ...scopeOptions]}
            />
          )}
          <Select
            label={t("filterStatus")}
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            options={[
              { value: "all", label: t("all") },
              { value: "enabled", label: t("enabled") },
              { value: "disabled", label: t("disabled") },
            ]}
          />
        </div>

        <div className="space-y-2">
          {visibleRules.length === 0 && <p className="text-sm text-text-muted">{t("empty")}</p>}
          {visibleRules.map((rule) => (
            <div
              key={rule.id}
              className="flex flex-wrap items-center gap-3 rounded-lg border border-border p-3"
            >
              <Toggle
                checked={rule.enabled}
                onChange={() => toggle(rule)}
                size="sm"
                ariaLabel={t("toggleAria", { name: rule.name })}
              />
              <div className="min-w-0 flex-1">
                <p className="font-medium text-text-main">{rule.name}</p>
                <p className="text-xs text-text-muted">
                  {t(`scope.${rule.scope}`)} · {rule.modelPattern || t("allModels")} ·{" "}
                  {rule.sourceEffort} →{" "}
                  {rule.targetKind === "keep"
                    ? t("keepModel")
                    : rule.targetModel || rule.targetComboId}{" "}
                  · {t(`mode.${rule.effortMode}`)}
                  {rule.targetEffort ? ` ${rule.targetEffort}` : ""} ·{" "}
                  {t("priorityShort", { value: rule.priority })}
                </p>
              </div>
              <Button size="sm" variant="ghost" icon="edit" onClick={() => edit(rule)}>
                {t("edit")}
              </Button>
              <Button size="sm" variant="danger" icon="delete" onClick={() => remove(rule.id)}>
                {t("delete")}
              </Button>
            </div>
          ))}
        </div>

        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <Input
            label={t("name")}
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            required
          />
          <Input
            label={t("description")}
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          {!apiKeyId && (
            <Select
              label={t("scopeLabel")}
              value={form.scope}
              onChange={(e) =>
                setForm({
                  ...form,
                  scope: e.target.value as RuleScope,
                  targetKind: e.target.value === "connection" ? "keep" : form.targetKind,
                })
              }
              options={scopeOptions}
            />
          )}
          {form.scope === "apiKey" && !apiKeyId && (
            <Select
              label={t("apiKey")}
              value={form.apiKeyId}
              onChange={(e) => setForm({ ...form, apiKeyId: e.target.value })}
              options={keys.map((key) => ({ value: key.id, label: key.name }))}
            />
          )}
