        {message && <p className="text-sm text-text-muted">{message}</p>}

        <div className="border-t border-border pt-5">
          <h4 className="mb-3 font-medium text-text-main">{t("simulateTitle")}</h4>
          <div className="grid gap-3 md:grid-cols-4">
            <Input
