"use client";

import { useState, useCallback } from "react";
import OAuthModal from "./OAuthModal";
import KiroAuthModal from "./KiroAuthModal";
import KiroSocialOAuthModal from "./KiroSocialOAuthModal";

type KiroOAuthWrapperProps = {
  isOpen: boolean;
  providerInfo?: { id?: string; name?: string } | null;
  onSuccess?: () => void;
  onClose: () => void;
  reauthConnection?: null | { id?: string };
};

/**
 * Kiro OAuth Wrapper
 * Orchestrates between method selection, device code flow, and social login flow
 */
export default function KiroOAuthWrapper({
  isOpen,
  providerInfo,
  onSuccess,
  onClose,
  reauthConnection,
}: KiroOAuthWrapperProps) {
  const [authMethod, setAuthMethod] = useState(null); // null | "builder-id" | "idc" | "social" | "import" | "api-key"
  const [socialProvider, setSocialProvider] = useState(null); // "google" | "github"
  const [idcConfig, setIdcConfig] = useState(null);

  const handleMethodSelect = useCallback(
    (method, config) => {
      if (method === "builder-id") {
        // Use device code flow (AWS Builder ID)
        setAuthMethod("builder-id");
      } else if (method === "idc") {
        // Use device code flow with IDC config
        setAuthMethod("idc");
        setIdcConfig(config);
      } else if (method === "social") {
        // Use social login with manual callback
        setAuthMethod("social");
        setSocialProvider(config.provider);
      } else if (method === "import") {
        // Import handled in KiroAuthModal, just close
        onSuccess?.();
      } else if (method === "api-key") {
        // API-key import is handled in KiroAuthModal.
        onSuccess?.();
      }
    },
    [onSuccess]
  );

  const handleBack = () => {
    setAuthMethod(null);
    setSocialProvider(null);
    setIdcConfig(null);
  };

  const handleSocialSuccess = useCallback(() => {
    setAuthMethod(null);
    setSocialProvider(null);
    onSuccess?.();
  }, [onSuccess]);

  const handleDeviceSuccess = () => {
    setAuthMethod(null);
    setIdcConfig(null);
    onSuccess?.();
  };

  // Show method selection first
  const oauthProviderId = providerInfo?.id || "kiro";
  const providerLabel = providerInfo?.name || "Kiro";

  if (!authMethod) {
    return (
      <KiroAuthModal
        isOpen={isOpen}
        providerId={oauthProviderId}
        providerLabel={providerLabel}
        onMethodSelect={handleMethodSelect}
        onClose={onClose}
      />
    );
  }

  // Show device code flow (Builder ID or IDC)
  if (authMethod === "builder-id" || authMethod === "idc") {
    return (
      <OAuthModal
        isOpen={isOpen}
        provider={oauthProviderId}
        providerInfo={providerInfo}
        onSuccess={handleDeviceSuccess}
        reauthConnection={reauthConnection}
        onClose={handleBack}
        idcConfig={idcConfig}
      />
    );
  }

  // Show social login flow (Google/GitHub with manual callback)
  if (authMethod === "social" && socialProvider) {
    return (
      <KiroSocialOAuthModal
        isOpen={isOpen}
        provider={socialProvider}
        targetProvider={oauthProviderId}
        providerLabel={providerLabel}
        onSuccess={handleSocialSuccess}
        onClose={handleBack}
      />
    );
  }

  return null;
}

"use client";

import { useState, useEffect, useRef } from "react";
import Modal from "./Modal";
import Button from "./Button";
import { copyToClipboard } from "@/shared/utils/clipboard";
import { getNextKiroSocialPollInterval } from "@/lib/oauth/kiroSocialPoll";

type KiroSocialOAuthModalProps = {
  isOpen: boolean;
  provider: "google" | "github";
  targetProvider?: string;
  providerLabel?: string;
  onSuccess?: () => void;
  onClose: () => void;
};

export default function KiroSocialOAuthModal({
  isOpen,
  provider,
  targetProvider,
  providerLabel = "Kiro",
  onSuccess,
  onClose,
}: KiroSocialOAuthModalProps) {
  const [step, setStep] = useState<"loading" | "polling" | "success" | "error">("loading");
  const [error, setError] = useState<string | null>(null);
  const [userCode, setUserCode] = useState("");
  const [authUrl, setAuthUrl] = useState("");
  const pollRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const onSuccessRef = useRef(onSuccess);

  useEffect(() => {
    onSuccessRef.current = onSuccess;
  }, [onSuccess]);

  useEffect(() => {
    if (!isOpen || !provider) return;
    let cancelled = false;

    const stopPolling = () => {
      if (pollRef.current) clearTimeout(pollRef.current);
      pollRef.current = null;
    };

    const fail = (message: string) => {
      stopPolling();
      if (cancelled) return;
      setError(message);
      setStep("error");
    };

    const initAuth = async () => {
      try {
        setError(null);
        setStep("loading");

        const res = await fetch(`/api/oauth/kiro/social-authorize?provider=${provider}`);
        const data = await res.json();
        if (cancelled) return;

        if (!res.ok) {
          throw new Error(data.error || "Failed to start authorization");
        }

        setUserCode(data.userCode || "");
        setAuthUrl(data.authUrl || "");
        setStep("polling");

        const baseIntervalMs = Math.max(1, Number(data.interval) || 5) * 1000;
        let currentIntervalMs = baseIntervalMs;
        const expiresAt = Date.now() + Math.max(1, Number(data.expiresIn) || 300) * 1000;

        const schedule = (delayMs: number) => {
          if (cancelled) return;
          pollRef.current = setTimeout(poll, delayMs);
        };

        const poll = async () => {
          pollRef.current = null;
          if (cancelled) return;
          if (Date.now() >= expiresAt) {
            fail("Authorization expired. Start the login flow again.");
            return;
          }

          try {
            const pollRes = await fetch("/api/oauth/kiro/social-exchange", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ deviceCode: data.deviceCode, provider, targetProvider }),
            });
            const pollData = await pollRes.json();
            if (cancelled) return;

            if (pollData.success) {
              stopPolling();
              setStep("success");
              onSuccessRef.current?.();
              return;
            }

            if (!pollData.pending) {
              fail(pollData.error || "Authorization failed");
              return;
            }

            currentIntervalMs = getNextKiroSocialPollInterval(currentIntervalMs, pollData.error);
            schedule(currentIntervalMs);
          } catch {
            schedule(currentIntervalMs);
          }
        };

        schedule(baseIntervalMs);
      } catch (err: any) {
        fail(err.message);
      }
    };

    initAuth();

    return () => {
      cancelled = true;
      stopPolling();
    };
  }, [isOpen, provider, targetProvider]);

  const handleClose = () => {
    if (pollRef.current) {
      clearTimeout(pollRef.current);
      pollRef.current = null;
    }
    onClose();
  };

  const providerName = provider === "google" ? "Google" : "GitHub";

  return (
    <Modal
      isOpen={isOpen}
      title={`Connect ${providerLabel} via ${providerName}`}
      onClose={handleClose}
      size="lg"
    >
      <div className="flex flex-col gap-4">
        {step === "loading" && (
          <div className="text-center py-6">
            <div className="size-16 mx-auto mb-4 rounded-full bg-primary/10 flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl text-primary animate-spin">
                progress_activity
              </span>
            </div>
            <h3 className="text-lg font-semibold mb-2">Initializing...</h3>
            <p className="text-sm text-text-muted">Setting up {providerName} authentication</p>
          </div>
        )}

        {step === "polling" && (
          <div className="text-center py-6">
            <div className="size-16 mx-auto mb-4 rounded-full bg-primary/10 flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl text-primary animate-pulse">
                open_in_browser
              </span>
            </div>
            <h3 className="text-lg font-semibold mb-2">Open this link in an Incognito window</h3>
            <p className="text-sm text-text-muted mb-3">
              Use an Incognito/Private window to avoid session conflicts with existing accounts.
            </p>
            {authUrl && (
              <div className="mb-4">
                <div className="flex items-center gap-2 justify-center">
                  <a
                    href={authUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-xs font-mono text-primary underline break-all max-w-md inline-block"
                  >
                    {authUrl.length > 80 ? authUrl.slice(0, 80) + "..." : authUrl}
                  </a>
                  <button
                    onClick={() => copyToClipboard(authUrl)}
                    className="shrink-0 p-1 rounded hover:bg-sidebar"
                    title="Copy link"
                  >
                    <span className="material-symbols-outlined text-base">content_copy</span>
                  </button>
                </div>
              </div>
            )}
            {userCode && (
              <div className="mb-4">
                <p className="text-xs text-text-muted mb-1">Verification code</p>
                <p className="font-mono text-2xl font-bold tracking-widest">{userCode}</p>
              </div>
            )}
            <div className="flex items-center justify-center gap-2 text-sm text-text-muted">
              <span className="material-symbols-outlined text-base animate-spin">
                progress_activity
              </span>
              Waiting for authorization...
            </div>
            <div className="mt-6">
              <Button onClick={handleClose} variant="ghost" fullWidth>
                Cancel
              </Button>
            </div>
          </div>
        )}

        {step === "success" && (
          <div className="text-center py-6">
            <div className="size-16 mx-auto mb-4 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl text-green-600">
                check_circle
              </span>
            </div>
            <h3 className="text-lg font-semibold mb-2">Connected Successfully!</h3>
            <p className="text-sm text-text-muted mb-4">
              Your {providerLabel} account via {providerName} has been connected.
            </p>
            <Button onClick={handleClose} fullWidth>
              Done
            </Button>
          </div>
        )}

        {step === "error" && (
          <div className="text-center py-6">
            <div className="size-16 mx-auto mb-4 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl text-red-600">error</span>
            </div>
            <h3 className="text-lg font-semibold mb-2">Connection Failed</h3>
            <p className="text-sm text-red-600 mb-4">{error}</p>
            <div className="flex gap-2">
              <Button onClick={handleClose} variant="ghost" fullWidth>
                Close
              </Button>
            </div>
          </div>
        )}
      </div>
    </Modal>
  );
}

export type KiroSocialPollData = {
  error?: unknown;
  accessToken?: unknown;
  refreshToken?: unknown;
};

export type KiroSocialPollOutcome =
  | { kind: "pending"; error: "authorization_pending" | "slow_down" }
  | { kind: "error"; error: string; status: number }
  | { kind: "success" };

/**
 * RFC 8628 requires every later device-code poll to retain a `slow_down`
 * increase. Keeping this transition pure makes the UI retry behaviour testable.
 */
export function getNextKiroSocialPollInterval(currentIntervalMs: number, error: unknown): number {
  return error === "slow_down" ? currentIntervalMs + 5000 : currentIntervalMs;
}

function errorCode(value: unknown): string {
  return typeof value === "string" && value.trim() ? value.trim() : "authorization_failed";
}

export function classifyKiroSocialPoll(
  responseOk: boolean,
  responseStatus: number,
  data: KiroSocialPollData
): KiroSocialPollOutcome {
  if (data.error === "authorization_pending" || data.error === "slow_down") {
    return { kind: "pending", error: data.error };
  }

  if (!responseOk || data.error) {
    const status = responseStatus >= 400 && responseStatus <= 599 ? responseStatus : 400;
    return { kind: "error", error: errorCode(data.error), status };
  }

  if (!data.accessToken && !data.refreshToken) {
    return { kind: "error", error: "invalid_token_response", status: 502 };
  }

  return { kind: "success" };
}

"use client";

import { useState, useEffect } from "react";
import { useTranslations } from "next-intl";
import Modal from "./Modal";
import Button from "./Button";
import Input from "./Input";

type CursorAuthModalProps = {
  isOpen: boolean;
  onSuccess?: () => void;
  onClose: () => void;
  reauthConnection?: unknown;
};

/**
 * Cursor Auth Modal
 * Auto-detect and import token from Cursor IDE's local SQLite database
 */
export default function CursorAuthModal({
  isOpen,
  onSuccess,
  onClose,
  reauthConnection: _,
}: CursorAuthModalProps) {
  const t = useTranslations("cursorAuthModal");
  const [accessToken, setAccessToken] = useState("");
  const [machineId, setMachineId] = useState("");
  const [error, setError] = useState(null);
  const [importing, setImporting] = useState(false);
  const [autoDetecting, setAutoDetecting] = useState(false);
  const [autoDetected, setAutoDetected] = useState(false);

  // Auto-detect tokens when modal opens
  useEffect(() => {
    if (!isOpen) return;

    const autoDetect = async () => {
      setAutoDetecting(true);
      setError(null);
      setAutoDetected(false);

      try {
        const res = await fetch("/api/oauth/cursor/auto-import");
        const data = await res.json();

        if (data.found) {
          setAccessToken(data.accessToken);
          setMachineId(data.machineId || "");
          setAutoDetected(true);
        } else {
          setError(data.error || t("errorAutoDetect"));
        }
      } catch (err) {
        setError(t("errorAutoDetectFailed"));
      } finally {
        setAutoDetecting(false);
      }
    };

    autoDetect();
  }, [isOpen]);

  const handleImportToken = async () => {
    if (!accessToken.trim()) {
      setError(t("errorEnterToken"));
      return;
    }

    setImporting(true);
    setError(null);

    try {
      const body: Record<string, string> = { accessToken: accessToken.trim() };
      if (machineId.trim()) body.machineId = machineId.trim();

      const res = await fetch("/api/oauth/cursor/import", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || t("errorImportFailed"));
      }

      // Success - close modal and trigger refresh
      onSuccess?.();
      onClose();
    } catch (err) {
      setError(err.message);
    } finally {
      setImporting(false);
    }
  };

  return (
    <Modal isOpen={isOpen} title={t("title")} onClose={onClose}>
      <div className="flex flex-col gap-4">
        {/* Auto-detecting state */}
        {autoDetecting && (
          <div className="text-center py-6">
            <div className="size-16 mx-auto mb-4 rounded-full bg-primary/10 flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl text-primary animate-spin">
                progress_activity
              </span>
            </div>
            <h3 className="text-lg font-semibold mb-2">{t("autoDetecting")}</h3>
            <p className="text-sm text-text-muted">{t("readingFromCursor")}</p>
          </div>
        )}

        {/* Form (shown after auto-detect completes) */}
        {!autoDetecting && (
          <>
            {/* Success message if auto-detected */}
            {autoDetected && (
              <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg border border-green-200 dark:border-green-800">
                <div className="flex gap-2">
                  <span className="material-symbols-outlined text-green-600 dark:text-green-400">
                    check_circle
                  </span>
                  <p className="text-sm text-green-800 dark:text-green-200">
                    {t("tokensAutoDetected")}
                  </p>
                </div>
              </div>
            )}

            {/* Info message if not auto-detected */}
            {!autoDetected && !error && (
              <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg border border-blue-200 dark:border-blue-800">
                <div className="flex gap-2">
                  <span className="material-symbols-outlined text-blue-600 dark:text-blue-400">
                    info
                  </span>
                  <p className="text-sm text-blue-800 dark:text-blue-200">
                    {t("cursorNotDetected")}
                  </p>
                </div>
              </div>
            )}

            {/* Access Token Input */}
            <div>
              <label className="block text-sm font-medium mb-2">
                {t("accessToken")} <span className="text-red-500">{t("required")}</span>
              </label>
              <textarea
                value={accessToken}
                onChange={(e) => setAccessToken(e.target.value)}
                placeholder={t("accessTokenPlaceholder")}
                rows={3}
                className="w-full px-3 py-2 text-sm font-mono border border-border rounded-lg bg-background focus:outline-none focus:border-primary resize-none"
              />
            </div>

            {/* Machine ID Input (optional — not needed for cursor-agent imports) */}
            <div>
              <label className="block text-sm font-medium mb-2">
                {t("machineId")} <span className="text-text-muted text-xs">{t("optional")}</span>
              </label>
              <Input
                value={machineId}
                onChange={(e) => setMachineId(e.target.value)}
                placeholder={t("machineIdPlaceholder")}
                className="font-mono text-sm"
              />
            </div>

            {/* Error Display */}
            {error && (
              <div className="bg-red-50 dark:bg-red-900/20 p-3 rounded-lg border border-red-200 dark:border-red-800">
                <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
              </div>
            )}

            {/* Action Buttons */}
            <div className="flex gap-2">
              <Button
                onClick={handleImportToken}
                fullWidth
                disabled={importing || !accessToken.trim()}
              >
                {importing ? t("importing") : t("importToken")}
              </Button>
              <Button onClick={onClose} variant="ghost" fullWidth>
                {t("cancel")}
              </Button>
            </div>
          </>
        )}
      </div>
    </Modal>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import Modal from "./Modal";
import Button from "./Button";
import Input from "./Input";

const TRAE_CLIENT_ID = "en1oxy7wnw8j9n";

function uuid(): string {
  const c = (globalThis.crypto || (globalThis as any).crypto) as Crypto | undefined;
  if (c?.randomUUID) return c.randomUUID();
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (ch) => {
    const r = (Math.random() * 16) | 0;
    return (ch === "x" ? r : (r & 0x3) | 0x8).toString(16);
  });
}

function randomHex(bytes: number): string {
  const buf = new Uint8Array(bytes);
  (globalThis.crypto || (globalThis as any).crypto).getRandomValues(buf);
  return Array.from(buf, (b) => b.toString(16).padStart(2, "0")).join("");
}

function randomDigits(n: number): string {
  let s = "";
  while (s.length < n) s += Math.floor(Math.random() * 1e10).toString();
  return s.slice(0, n);
}

function buildTraeAuthorizeUrl(callbackUrl: string, traceId: string): string {
  // Per-attempt machine/device IDs — Trae doesn't tie tokens to a specific
  // machine_id, but the field is required and is echoed into provider metadata.
  const machineId = randomHex(32);
  const deviceId = randomDigits(19);
  const params = new URLSearchParams({
    login_version: "1",
    auth_from: "solo",
    login_channel: "native_ide",
    plugin_version: "2.3.24254",
    auth_type: "local",
    client_id: TRAE_CLIENT_ID,
    redirect: "0",
    login_trace_id: traceId,
    auth_callback_url: callbackUrl,
    machine_id: machineId,
    device_id: deviceId,
    x_device_id: deviceId,
    x_machine_id: machineId,
    x_device_brand: "Mac14,7",
    x_device_type: "mac",
    x_os_version: "macOS 26.4.1",
    x_env: "",
    x_app_version: "0.1.7",
    x_app_type: "stable",
    // Match what the SOLO desktop client sends: hide_saas_login=true. With
    // auth_from=solo, trae.ai's authorize page is *only* a confirmation gate
    // for an already-cookied session — so leaving the SaaS sign-in surface
    // visible (false) causes the server to short-circuit to "Login Failed".
    // The user must be signed in on trae.ai in the same browser; we surface
    // that in the modal copy and provide an "Open solo.trae.ai" button.
    hide_saas_login: "true",
  });
  return `https://www.trae.ai/authorization?${params.toString()}`;
}

type TraeAuthModalProps = {
  isOpen: boolean;
  onSuccess?: () => void;
  onClose: () => void;
  reauthConnection?: unknown;
};

/**
 * Trae SOLO Auth Modal — paste the Cloud-IDE-JWT from solo.trae.ai.
 *
 * Trae has no public OAuth or local credential store like Cursor: the user
 * signs in to solo.trae.ai in a browser, copies the JWT sent in the
 * Authorization header (Cloud-IDE-JWT scheme), and pastes it here. JWT
 * lifetime is ~14 days; re-import on expiry.
 */
export default function TraeAuthModal({
  isOpen,
  onSuccess,
  onClose,
  reauthConnection: _,
}: TraeAuthModalProps) {
  const [accessToken, setAccessToken] = useState("");
  const [webId, setWebId] = useState("");
  const [bizUserId, setBizUserId] = useState("");
  const [userUniqueId, setUserUniqueId] = useState("");
  const [scope, setScope] = useState("marscode-us");
  const [tenant, setTenant] = useState("marscode");
  const [region, setRegion] = useState("US-East");
  const [error, setError] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);
  const [authorizing, setAuthorizing] = useState(false);
  const popupRef = useRef<Window | null>(null);
  const traceIdRef = useRef<string | null>(null);

  // Listen for postMessage from the callback page (window.opener.postMessage).
  // Only act on messages with our type tag, and verify the loginTraceId matches
  // the one we sent in the authorize URL — protects against unrelated postMessages.
  useEffect(() => {
    if (!isOpen) return;
    const onMessage = (ev: MessageEvent) => {
      const m = ev.data as {
        type?: string;
        success?: boolean;
        error?: string;
        loginTraceId?: string;
      } | null;
      if (!m || m.type !== "trae-oauth-callback") return;
      // Accept this window's origin OR the sibling loopback host: the dashboard
      // usually runs on localhost while Trae forces the callback onto 127.0.0.1,
      // so they are different origins by design. Restrict to that known pair
      // (never wildcard), then rely on the random loginTraceId for CSRF.
      const here = window.location;
      const altHost =
        here.hostname === "127.0.0.1"
          ? "localhost"
          : here.hostname === "localhost"
            ? "127.0.0.1"
            : null;
      const allowedOrigins = new Set([here.origin]);
      if (altHost)
        allowedOrigins.add(`${here.protocol}//${altHost}${here.port ? `:${here.port}` : ""}`);
      if (!allowedOrigins.has(ev.origin)) return;
      if (!traceIdRef.current || m.loginTraceId !== traceIdRef.current) return;
      setAuthorizing(false);
      if (m.success) {
        onSuccess?.();
        onClose();
      } else {
        setError(m.error || "Authorization failed");
      }
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, [isOpen, onSuccess, onClose]);

  const handleAuthorizeWithBrowser = () => {
    setError(null);
    setAuthorizing(true);
    const traceId = uuid();
    traceIdRef.current = traceId;
    // Trae's authorize endpoint validates two things about auth_callback_url:
    //  1. host must be a loopback IP (127.0.0.1) — "localhost" hostname gets
    //     rejected with "Login Failed".
    //  2. path must end with `/authorize` — any other path (e.g. our earlier
    //     "/api/oauth/trae/callback") also short-circuits to "Login Failed".
    // The receiving handler therefore lives at the app root (src/app/authorize).
    const port = window.location.port || (window.location.protocol === "https:" ? "443" : "80");
    const callbackUrl = `http://127.0.0.1:${port}/authorize`;
    const authUrl = buildTraeAuthorizeUrl(callbackUrl, traceId);
    const w = window.open(authUrl, "trae-oauth", "width=520,height=720");
    if (!w) {
      setAuthorizing(false);
      setError("Popup blocked — allow popups for this site, or paste the token manually below.");
      return;
    }
    popupRef.current = w;
    // If the user closes the popup without completing, drop the spinner.
    const poll = setInterval(() => {
      if (w.closed) {
        clearInterval(poll);
        setAuthorizing((prev) => {
          if (prev) setError("Authorization window was closed before completing.");
          return false;
        });
      }
    }, 700);
  };

  const handleImportToken = async () => {
    if (!accessToken.trim()) {
      setError("Access token is required.");
      return;
    }
    setImporting(true);
    setError(null);
    try {
      const body: Record<string, string> = { accessToken: accessToken.trim() };
      if (webId.trim()) body.webId = webId.trim();
      if (bizUserId.trim()) body.bizUserId = bizUserId.trim();
      if (userUniqueId.trim()) body.userUniqueId = userUniqueId.trim();
      if (scope.trim()) body.scope = scope.trim();
      if (tenant.trim()) body.tenant = tenant.trim();
      if (region.trim()) body.region = region.trim();

      const res = await fetch("/api/oauth/trae/import", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(
          typeof data.error === "string" ? data.error : data.error?.message || "Import failed"
        );
      }
      onSuccess?.();
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setImporting(false);
    }
  };

  return (
    <Modal isOpen={isOpen} title="Connect Trae SOLO" onClose={onClose}>
      <div className="flex flex-col gap-4">
        {/* Primary path: browser-based OAuth via trae.ai/authorization */}
        <div className="bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-lg border border-emerald-200 dark:border-emerald-800">
          <p className="text-sm text-emerald-900 dark:text-emerald-200 mb-2">
            Authorize via <span className="font-mono">trae.ai</span> in a popup. The popup will
            close itself once the token has been imported.
          </p>
          <p className="text-xs text-emerald-800 dark:text-emerald-300 mb-3">
            <strong>Important:</strong> you must be logged in to{" "}
            <span className="font-mono">trae.ai</span> in <em>this</em> browser first. The authorize
            page only confirms an existing session — it cannot sign you in. If you see &quot;Login
            Failed&quot;, click &quot;Open solo.trae.ai&quot;, sign in, then return here.
          </p>
          <div className="flex gap-2">
            <Button onClick={handleAuthorizeWithBrowser} disabled={authorizing} fullWidth>
              {authorizing ? "Waiting for trae.ai…" : "Authorize with Browser"}
            </Button>
            <Button
              onClick={() => window.open("https://solo.trae.ai/", "_blank", "noopener,noreferrer")}
              variant="ghost"
              fullWidth
            >
              Open solo.trae.ai
            </Button>
          </div>
        </div>

        <div className="flex items-center gap-3 text-xs text-text-muted">
          <span className="flex-1 border-t border-border" />
          or paste a token manually
          <span className="flex-1 border-t border-border" />
        </div>

        <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg border border-blue-200 dark:border-blue-800">
          <p className="text-sm text-blue-800 dark:text-blue-200">
            Sign in to <span className="font-mono">solo.trae.ai</span>, open DevTools → Network,
            send any chat message, and copy the JWT from the{" "}
            <span className="font-mono">Authorization: Cloud-IDE-JWT &lt;token&gt;</span> request
            header. JWT lifetime is ~14 days. Optional identity fields come from{" "}
            <span className="font-mono">common_params</span> in the same request body.
          </p>
        </div>

        <div>
          <label className="block text-sm font-medium mb-2">
            Access Token (Cloud-IDE-JWT) <span className="text-red-500">*</span>
          </label>
          <textarea
            value={accessToken}
            onChange={(e) => setAccessToken(e.target.value)}
            placeholder="eyJhbGciOiJSUzI1NiIs..."
            rows={3}
            className="w-full px-3 py-2 text-sm font-mono border border-border rounded-lg bg-background focus:outline-none focus:border-primary resize-none"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <div>
            <label className="block text-sm font-medium mb-1">
              Web ID <span className="text-text-muted text-xs">optional</span>
            </label>
            <Input
              value={webId}
              onChange={(e) => setWebId(e.target.value)}
              placeholder="76428..."
              className="font-mono text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">
              Biz User ID <span className="text-text-muted text-xs">optional</span>
            </label>
            <Input
              value={bizUserId}
              onChange={(e) => setBizUserId(e.target.value)}
              placeholder="76428..."
              className="font-mono text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">
              User Unique ID <span className="text-text-muted text-xs">optional</span>
            </label>
            <Input
              value={userUniqueId}
              onChange={(e) => setUserUniqueId(e.target.value)}
              placeholder="76428..."
              className="font-mono text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Scope</label>
            <Input value={scope} onChange={(e) => setScope(e.target.value)} className="text-sm" />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Tenant</label>
            <Input value={tenant} onChange={(e) => setTenant(e.target.value)} className="text-sm" />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Region</label>
            <Input value={region} onChange={(e) => setRegion(e.target.value)} className="text-sm" />
          </div>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 p-3 rounded-lg border border-red-200 dark:border-red-800">
            <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
          </div>
        )}

        <div className="flex gap-2">
          <Button onClick={handleImportToken} fullWidth disabled={importing || !accessToken.trim()}>
            {importing ? "Importing…" : "Import Token"}
          </Button>
          <Button onClick={onClose} variant="ghost" fullWidth>
            Cancel
          </Button>
        </div>
      </div>
    </Modal>
  );
}

